def longestWordFromDeletion(s, words):
    best = ""
    for w in words.split(","):
        pos = 0
        ok = True
        for c in w:
            pos = s.find(c, pos)
            if pos < 0:
                ok = False
                break
            pos += 1
        if ok and (len(w) > len(best) or (len(w) == len(best) and w < best)):
            best = w
    return best if best else "-"
